  void _showLockedOutHelpDialog(BuildContext context) {
    final recoveryInputController = TextEditingController();
    bool isSubmitting = false;
    String? errorMessage;
    String? successMessage;

    showDialog(
      context: context,
      builder: (BuildContext dialogContext) {
        return StatefulBuilder(
          builder: (context, setDialogState) {
            Future<void> handlePasswordReset() async {
              final rawInput = recoveryInputController.text.trim();
              if (rawInput.isEmpty) {
                setDialogState(() {
                  errorMessage =
                      "Por favor ingresa tu número de empleado o correo";
                  successMessage = null;
                });
                return;
              }

              setDialogState(() {
                isSubmitting = true;
                errorMessage = null;
                successMessage = null;
              });

              String? targetEmail;

              try {
                if (rawInput.contains('@')) {
                  targetEmail = rawInput.toLowerCase();
                } else {
                  // Resolve email via 'employee_directory' doc(rawInput)
                  final dirDoc = await FirebaseFirestore.instance
                      .collection('employee_directory')
                      .doc(rawInput)
                      .get();
                  if (dirDoc.exists) {
                    final d = dirDoc.data();
                    targetEmail = (d?['email'] ?? d?['recovery_email'])
                        ?.toString()
                        .trim()
                        .toLowerCase();
                  }

                  // Fallback check in users collection
                  if (targetEmail == null || targetEmail.isEmpty) {
                    final snapEmp = await FirebaseFirestore.instance
                        .collection('users')
                        .where('employee_number', isEqualTo: rawInput)
                        .limit(1)
                        .get();
                    if (snapEmp.docs.isNotEmpty) {
                      final data = snapEmp.docs.first.data();
                      targetEmail = (data['recovery_email'] ?? data['email'])
                          ?.toString()
                          .trim()
                          .toLowerCase();
                    }
                    if (targetEmail == null || targetEmail.isEmpty) {
                      final snapUserEmp = await FirebaseFirestore.instance
                          .collection('users')
                          .where('user_emp', isEqualTo: rawInput)
                          .limit(1)
                          .get();
                      if (snapUserEmp.docs.isNotEmpty) {
                        final data = snapUserEmp.docs.first.data();
                        targetEmail = (data['recovery_email'] ?? data['email'])
                            ?.toString()
                            .trim()
                            .toLowerCase();
                      }
                    }
                  }
                }

                if (targetEmail == null ||
                    targetEmail.isEmpty ||
                    targetEmail.endsWith('@televisa.com')) {
                  setDialogState(() {
                    isSubmitting = false;
                    errorMessage = rawInput.contains('@')
                        ? "El correo no está registrado en el sistema"
                        : "El número de empleado no tiene un correo de recuperación registrado";
                  });
                  return;
                }

                await FirebaseAuth.instance
                    .sendPasswordResetEmail(email: targetEmail);

                setDialogState(() {
                  isSubmitting = false;
                  successMessage =
                      "Enlace enviado a $targetEmail. Revisa tu bandeja o carpeta de spam.";
                  errorMessage = null;
                });
              } on FirebaseAuthException catch (e) {
                setDialogState(() {
                  isSubmitting = false;
                  if (e.code == 'user-not-found') {
                    errorMessage =
                        "No se encontró ningún usuario con ese correo";
                  } else if (e.code == 'invalid-email') {
                    errorMessage = "El formato de correo no es válido";
                  } else {
                    errorMessage = e.message ??
                        "Error al enviar el enlace de recuperación";
                  }
                });
              } catch (e) {
                setDialogState(() {
                  isSubmitting = false;
                  errorMessage = "Error: ${e.toString()}";
                });
              }
            }

            return AlertDialog(
              backgroundColor: const Color(0xFF1E1E1E),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(16),
                side: BorderSide(color: Colors.white.withAlpha(25)),
              ),
              title: Column(
                children: [
                  Container(
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: Colors.orange.withAlpha(25),
                      shape: BoxShape.circle,
                    ),
                    child: const Icon(
                      Icons.lock_reset_rounded,
                      color: Colors.orange,
                      size: 38,
                    ),
                  ),
                  const SizedBox(height: 12),
                  const Text(
                    "Recuperar Contraseña",
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                    ),
                    textAlign: TextAlign.center,
                  ),
                ],
              ),
              content: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Text(
                      "Ingresa tu número de empleado o correo registrado. Te enviaremos un enlace oficial para restablecer tu contraseña.",
                      style: TextStyle(
                          color: Colors.white70, fontSize: 13.5, height: 1.35),
                      textAlign: TextAlign.center,
                    ),
                    const SizedBox(height: 18),
                    TextField(
                      controller: recoveryInputController,
                      style: const TextStyle(color: Colors.white, fontSize: 16),
                      enabled: !isSubmitting && successMessage == null,
                      onChanged: (_) {
                        if (errorMessage != null || successMessage != null) {
                          setDialogState(() {
                            errorMessage = null;
                            successMessage = null;
                          });
                        }
                      },
                      decoration: InputDecoration(
                        labelText: "Número de empleado o correo registrado",
                        hintText: "Ej: 12345 o tu-correo@gmail.com",
                        prefixIcon: const Icon(Icons.person_search_rounded,
                            color: Colors.orange),
                        filled: true,
                        fillColor: Colors.white.withAlpha(12),
                        contentPadding: const EdgeInsets.symmetric(
                            horizontal: 14, vertical: 14),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(12),
                          borderSide: const BorderSide(color: Colors.white24),
                        ),
                        enabledBorder: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(12),
                          borderSide: const BorderSide(color: Colors.white24),
                        ),
                        focusedBorder: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(12),
                          borderSide:
                              const BorderSide(color: Colors.orange, width: 2),
                        ),
                        labelStyle: const TextStyle(
                            color: Colors.orange,
                            fontSize: 14,
                            fontWeight: FontWeight.bold),
                        hintStyle: const TextStyle(
                            color: Colors.white30, fontSize: 13.5),
                      ),
                    ),
                    if (errorMessage != null) ...[
                      const SizedBox(height: 14),
                      Container(
                        padding: const EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: Colors.red.withAlpha(30),
                          borderRadius: BorderRadius.circular(10),
                          border:
                              Border.all(color: Colors.redAccent.withAlpha(120)),
                        ),
                        child: Row(
                          children: [
                            const Icon(Icons.error_outline_rounded,
                                color: Colors.redAccent, size: 20),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Text(
                                errorMessage!,
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 13),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                    if (successMessage != null) ...[
                      const SizedBox(height: 14),
                      Container(
                        padding: const EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: Colors.green.withAlpha(30),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(
                              color: Colors.greenAccent.withAlpha(120)),
                        ),
                        child: Row(
                          children: [
                            const Icon(Icons.check_circle_outline_rounded,
                                color: Colors.greenAccent, size: 22),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Text(
                                successMessage!,
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 13.5,
                                    height: 1.3),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: isSubmitting
                      ? null
                      : () => Navigator.pop(dialogContext),
                  child: Text(
                    successMessage != null ? "CERRAR" : "CANCELAR",
                    style: const TextStyle(
                        color: Colors.white60, fontWeight: FontWeight.bold),
                  ),
                ),
                if (successMessage == null)
                  ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.orange,
                      shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(10)),
                      padding: const EdgeInsets.symmetric(
                          horizontal: 16, vertical: 10),
                    ),
                    onPressed: isSubmitting ? null : handlePasswordReset,
                    child: isSubmitting
                        ? const SizedBox(
                            width: 18,
                            height: 18,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              valueColor:
                                  AlwaysStoppedAnimation<Color>(Colors.black),
                            ),
                          )
                        : const Text(
                            "ENVIAR ENLACE",
                            style: TextStyle(
                                color: Colors.black,
                                fontWeight: FontWeight.bold),
                          ),
                  ),
              ],
            );
          },
        );
      },
    );
  }

  // REMOVED: _showPasswordResetSuccessDialog - now inline in Settings tab
  // The login screen no longer has password reset functionality
  // Users must use Settings tab when logged in, or contact admin if locked out
}

double getNumericParamForDate(
    DateTime date, List<dynamic> history, double fallback) {
  final targetDate = DateTime(date.year, date.month, date.day);
  if (history.isEmpty) return fallback;

  List<Map<String, dynamic>> matching = [];

  for (var raw in history) {
    if (raw is! Map) continue;
    final entry = Map<String, dynamic>.from(raw);

    DateTime? startDate;
    if (entry['start_date'] != null &&
        entry['start_date'].toString().isNotEmpty) {
      startDate = DateTime.tryParse(entry['start_date'].toString());
    } else if (entry['effective_date'] != null &&
        entry['effective_date'].toString().isNotEmpty) {
      startDate = DateTime.tryParse(entry['effective_date'].toString());
    }
    if (startDate == null) continue;
    final normalizedStart =
        DateTime(startDate.year, startDate.month, startDate.day);

    DateTime? endDate;
    if (entry['end_date'] != null && entry['end_date'].toString().isNotEmpty) {
      final parsedEnd = DateTime.tryParse(entry['end_date'].toString());
      if (parsedEnd != null) {
        endDate = DateTime(parsedEnd.year, parsedEnd.month, parsedEnd.day);
      }
    }

    // Check if targetDate is in [normalizedStart, endDate ?? Present]
    if (!targetDate.isBefore(normalizedStart)) {
      if (endDate == null || !targetDate.isAfter(endDate)) {
        matching.add({
          'entry': entry,
          'start': normalizedStart,
          'end': endDate,
        });
      }
    }
  }

  if (matching.isEmpty) {
    // Backwards compatibility for legacy salary_history with 'previous_salary'
    DateTime? earliestStart;
    dynamic earliestVal;
    for (var raw in history) {
      if (raw is! Map) continue;
      final entry = Map<String, dynamic>.from(raw);
      DateTime? s = DateTime.tryParse(
          (entry['start_date'] ?? entry['effective_date'] ?? '').toString());
      if (s != null) {
        if (earliestStart == null || s.isBefore(earliestStart)) {
          earliestStart = s;
          earliestVal = entry['previous_salary'] ?? entry['previous_value'];
        }
      }
    }
    if (earliestVal != null &&
        earliestStart != null &&
        targetDate.isBefore(earliestStart)) {
      if (earliestVal is num) return earliestVal.toDouble();
      return double.tryParse(earliestVal.toString()) ?? fallback;
    }
    return fallback;
  }

  // Sort matching entries: highest start_date first (most specific/latest period)
  matching.sort(
      (a, b) => (b['start'] as DateTime).compareTo(a['start'] as DateTime));
  final chosen = matching.first['entry'] as Map<String, dynamic>;
  final val = chosen['value'] ?? chosen['salary'];
  if (val is num) return val.toDouble();
  if (val != null) {
    return double.tryParse(val.toString()) ?? fallback;
  }
  return fallback;
}

List<int> getRestDaysForDate(
    DateTime date, List<dynamic> history, List<int> fallback) {
  final targetDate = DateTime(date.year, date.month, date.day);
  if (history.isEmpty) return fallback;

  List<Map<String, dynamic>> matching = [];

  for (var raw in history) {
    if (raw is! Map) continue;
    final entry = Map<String, dynamic>.from(raw);

    DateTime? startDate;
    if (entry['start_date'] != null &&
        entry['start_date'].toString().isNotEmpty) {
      startDate = DateTime.tryParse(entry['start_date'].toString());
    } else if (entry['effective_date'] != null &&
        entry['effective_date'].toString().isNotEmpty) {
      startDate = DateTime.tryParse(entry['effective_date'].toString());
    }
    if (startDate == null) continue;
    final normalizedStart =
        DateTime(startDate.year, startDate.month, startDate.day);

    DateTime? endDate;
    if (entry['end_date'] != null && entry['end_date'].toString().isNotEmpty) {
      final parsedEnd = DateTime.tryParse(entry['end_date'].toString());
      if (parsedEnd != null) {
        endDate = DateTime(parsedEnd.year, parsedEnd.month, parsedEnd.day);
      }
    }

    // Check if targetDate is in [normalizedStart, endDate ?? Present]
    if (!targetDate.isBefore(normalizedStart)) {
      if (endDate == null || !targetDate.isAfter(endDate)) {
        matching.add({
          'entry': entry,
          'start': normalizedStart,
          'end': endDate,
        });
      }
    }
  }

  if (matching.isEmpty) {
    return fallback;
  }

  // Sort matching entries: highest start_date first (most specific/latest period)
  matching.sort(
      (a, b) => (b['start'] as DateTime).compareTo(a['start'] as DateTime));
  final chosen = matching.first['entry'] as Map<String, dynamic>;
  final rawDays = chosen['rest_days'];
  if (rawDays is List) {
    final parsed = rawDays
        .map((e) => int.tryParse(e.toString()) ?? (e is int ? e : null))
        .whereType<int>()
        .where((d) => d >= 1 && d <= 7)
        .toList();
    if (parsed.isNotEmpty) {
      parsed.sort();
      return parsed;
    }
  }
  return fallback;
}

class WorkDay {
  static List<int> restDays = [DateTime.saturday, DateTime.sunday];
  static List<Map<String, dynamic>> restDaysHistory = [];
  static List<Map<String, dynamic>> salaryHistory = [];
  static List<Map<String, dynamic>> jornadaHistory = [];
  static double defaultSalary = 0.0;
  static double defaultJornada = 9.5;

  List<int> get applicableRestDays =>
      getRestDaysForDate(entrada, restDaysHistory, restDays);

  bool get isRestDay => applicableRestDays.contains(entrada.weekday);

  DateTime entrada;
  DateTime salida;
  DateTime? entradaReal; // Actual clock-in time (when button was pressed)
  double _storedSueldoBase;
  double _storedBaseHours;
  String id;
  bool isInProgress;
  bool esFalta;
  bool esMantenimiento;
  bool esVacaciones;
  bool esFestivo;
  bool festivoTrabajado;
  String notas;

  WorkDay(
      {required this.entrada,
      required this.salida,
      this.entradaReal,
      double sueldoBase = 0.0,
      double baseHours = 9.5,
      this.isInProgress = false,
      this.esFalta = false,
      this.esMantenimiento = false,
      this.esVacaciones = false,
      this.esFestivo = false,
      this.festivoTrabajado = false,
      this.notas = "",
      String? id})
      : _storedSueldoBase = sueldoBase,
        _storedBaseHours = baseHours,
        id = id ?? DateTime.now().millisecondsSinceEpoch.toString();

  double get sueldoBase {
    if (salaryHistory.isNotEmpty) {
      return getNumericParamForDate(
          entrada, salaryHistory, _storedSueldoBase > 0 ? _storedSueldoBase : defaultSalary);
    }
    return _storedSueldoBase > 0 ? _storedSueldoBase : defaultSalary;
  }

  set sueldoBase(double val) => _storedSueldoBase = val;

  double get baseHours {
    if (jornadaHistory.isNotEmpty) {
      return getNumericParamForDate(
          entrada, jornadaHistory, _storedBaseHours > 0 ? _storedBaseHours : defaultJornada);
    }
    return _storedBaseHours > 0 ? _storedBaseHours : defaultJornada;
  }

  set baseHours(double val) => _storedBaseHours = val;

  DateTime get effectiveStart {
    if (entradaReal != null && entradaReal!.isAfter(entrada)) {
      return entradaReal!;
    }
    return entrada;
  }

  int get requiredShiftMinutes => (baseHours * 60).round();

  DateTime get requiredCompletionTime =>
      effectiveStart.add(Duration(minutes: requiredShiftMinutes));

  int get actualWorkedMinutes {
    if (isInProgress) return 0;
    return salida.isAfter(effectiveStart)
        ? salida.difference(effectiveStart).inMinutes
        : 0;
  }

  double get totalHours {
    if (isInProgress) return 0.0;
    return (esFalta || esVacaciones || (esFestivo && !festivoTrabajado))
        ? 0.0
        : actualWorkedMinutes / 60.0;
  }

  bool get isOvernight => salida.day != entrada.day;

  double get hourlyRate => baseHours > 0 ? sueldoBase / baseHours : 0.0;

  double get payDeduction {
    if (isInProgress ||
        esFalta ||
        esMantenimiento ||
        esVacaciones ||
        esFestivo) {
      return 0.0;
    }
    if (actualWorkedMinutes < requiredShiftMinutes) {
      int shortfallMinutes = requiredShiftMinutes - actualWorkedMinutes;
      int deficitBlocks = (shortfallMinutes / 30.0).ceil();
      return deficitBlocks * 0.5 * hourlyRate;
    }
    return 0.0;
  }

  double get dailyPay {
    if (isInProgress || esFalta) return 0.0;
    bool restDay = isRestDay;
    double baseDailyPay = restDay ? sueldoBase * 2 : sueldoBase;
    if (esMantenimiento || esVacaciones || (esFestivo && !festivoTrabajado)) {
      return baseDailyPay;
    }
    if (esFestivo && festivoTrabajado) return baseDailyPay * 2;

    double pay = baseDailyPay - payDeduction;
    return pay < 0 ? 0.0 : pay;
  }

  double get creditedExtraHours {
    if (isInProgress ||
        esFalta ||
        esMantenimiento ||
        esVacaciones ||
        (esFestivo && !festivoTrabajado)) {
      return 0.0;
    }
    if (actualWorkedMinutes <= requiredShiftMinutes) return 0.0;

    int extraMinutes = actualWorkedMinutes - requiredShiftMinutes;
    int hourBlock = extraMinutes ~/ 60;
    int remainder = extraMinutes % 60;

    double bonus = remainder <= 20 ? 0.0 : (remainder <= 50 ? 0.5 : 1.0);
    return hourBlock + bonus;
  }

  double get extraHoursCount => creditedExtraHours;

  double get extrasMoney {
    if (isInProgress ||
        esFalta ||
        esMantenimiento ||
        esVacaciones ||
        (esFestivo && !festivoTrabajado)) {
      return 0.0;
    }
    if (creditedExtraHours <= 0) return 0.0;
    if (esFestivo && festivoTrabajado) {
      return creditedExtraHours * (hourlyRate * 3);
    }
    if (isRestDay) {
      return creditedExtraHours * (hourlyRate * 3);
    }
    return creditedExtraHours * (hourlyRate * 2);
  }

  double get holidayExtraHours =>
      (isInProgress || !(esFestivo && festivoTrabajado))
          ? 0.0
          : creditedExtraHours;

  double get holidayExtrasPay =>
      (isInProgress ||
              !(esFestivo && festivoTrabajado && creditedExtraHours > 0))
          ? 0.0
          : creditedExtraHours * (hourlyRate * 3);

  double get totalPay => (isInProgress) ? 0.0 : (dailyPay + extrasMoney);

  Map<String, dynamic> toJson() => {
        'entrada': entrada.toIso8601String(),
        'salida': salida.toIso8601String(),
        'entradaReal': entradaReal?.toIso8601String(),
        'sueldoBase': sueldoBase,
        'baseHours': baseHours,
        'id': id,
        'isInProgress': isInProgress,
        'esFalta': esFalta,
        'esMantenimiento': esMantenimiento,
        'esVacaciones': esVacaciones,
        'esFestivo': esFestivo,
        'festivoTrabajado': festivoTrabajado,
        'notas': notas,
      };
  factory WorkDay.fromJson(Map<String, dynamic> json) => WorkDay(
        entrada: DateTime.parse(json['entrada']),
        salida: DateTime.parse(json['salida']),
        entradaReal: json['entradaReal'] != null
            ? DateTime.parse(json['entradaReal'])
            : null,
        sueldoBase: (json['sueldoBase'] ?? 0).toDouble(),
        baseHours: (json['baseHours'] ?? 9.5).toDouble(),
        id: json['id'],
        isInProgress: json['isInProgress'] ?? false,
        esFalta: json['esFalta'] ?? false,
        esMantenimiento: json['esMantenimiento'] ?? false,
        esVacaciones:
            json['esVacaciones'] ?? json['esVacacionesFestivo'] ?? false,
        esFestivo: json['esFestivo'] ?? false,
        festivoTrabajado: json['festivoTrabajado'] ?? false,
        notas: json['notas'] ?? "",
      );
}

class OvertimeBreakdown {
  double hours2x;
  double pay2x;
  double hours3x;
  double pay3x;
  OvertimeBreakdown({
    this.hours2x = 0,
    this.pay2x = 0,
    this.hours3x = 0,
    this.pay3x = 0,
  });
  double get totalPay => pay2x + pay3x;
}

