                          : () {
                              DateTime now = DateTime.now();
                              DateTime noon =
                                  DateTime(now.year, now.month, now.day, 12, 0);
                              final double salaryForDate =
                                  _getSalaryForDate(noon);

                              _addAndSortHistory(WorkDay(
