          Text(label,
              style: TextStyle(
                  color: _isDarkMode ? Colors.white60 : Colors.black87,
                  fontSize: 11,
                  fontWeight: FontWeight.bold)),
          Text(breakdown,
              style: TextStyle(
                  color: _isDarkMode ? Colors.white : Colors.black,
                  fontSize: 13)),
          Text(total,
              style: TextStyle(
                  color: isMoney
                      ? (_isDarkMode ? Colors.greenAccent : const Color(0xFF2E7D32))
                      : (_isDarkMode ? Colors.white : Colors.black),
                  fontSize: 18,
                  fontWeight: FontWeight.w900))
        ]));
  }

  Future<TimeOfDay?> _showScrollTimePicker(
    BuildContext context, {
    required TimeOfDay initialTime,
    String? title,
    bool forceScrollMode = false,
  }) async {
    if (!forceScrollMode) {
      // MODE 1: Unsquished Native Analog Clock (Default)
      bool switchRequested = false;
      final TimeOfDay? picked = await showTimePicker(
        context: context,
        initialTime: initialTime,
        cancelText: "CANCELAR",
        confirmText: "CONFIRMAR",
        helpText: title ?? "SELECCIONAR HORA",
        builder: (BuildContext context, Widget? child) {
          return Theme(
            data: ThemeData.dark().copyWith(
              colorScheme: const ColorScheme.dark(
                primary: Colors.orange,
                onPrimary: Colors.black,
                surface: Color(0xFF1E1E1E),
                onSurface: Colors.white,
              ),
              timePickerTheme: const TimePickerThemeData(
                backgroundColor: Color(0xFF1E1E1E),
                hourMinuteTextColor: Colors.orange,
                hourMinuteColor: Color(0xFF2C2C2C),
                dialHandColor: Colors.orange,
                dialBackgroundColor: Color(0xFF2C2C2C),
                dialTextColor: Colors.white,
                entryModeIconColor: Colors.orangeAccent,
              ),
            ),
            child: Stack(
              children: [
                child!,
                Positioned(
                  top: 14,
                  right: 14,
                  child: IconButton(
                    icon: const Icon(Icons.unfold_more_rounded,
                        color: Colors.orangeAccent, size: 24),
                    tooltip: "Cambiar a Rodillo",
                    onPressed: () {
                      switchRequested = true;
                      Navigator.pop(context, null);
                    },
                  ),
                ),
              ],
            ),
          );
        },
      );

      if (switchRequested) {
        if (!context.mounted) return null;
        return await _showScrollTimePicker(
          context,
          initialTime: initialTime,
          title: title,
          forceScrollMode: true,
        );
      }
      return picked;
    }

    // MODE 2: Cupertino Vertical Scroll Wheel
    DateTime now = DateTime.now();
    DateTime selectedDateTime = DateTime(
      now.year,
      now.month,
      now.day,
      initialTime.hour,
      initialTime.minute,
    );
    bool switchRequested = false;

    final TimeOfDay? result = await showModalBottomSheet<TimeOfDay>(
      context: context,
      backgroundColor: const Color(0xFF1E1E1E),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (BuildContext builderContext) {
        return Container(
          height: 310,
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              // Responsive Header Bar
              Row(
                children: [
                  // CANCELAR
                  Flexible(
                    fit: FlexFit.loose,
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      alignment: Alignment.centerLeft,
                      child: TextButton(
                        style: TextButton.styleFrom(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 6, vertical: 4),
                          minimumSize: Size.zero,
                          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                        ),
                        onPressed: () => Navigator.pop(builderContext, null),
                        child: const Text(
                          "CANCELAR",
                          style: TextStyle(
                              color: Colors.white54,
                              fontSize: 13,
                              fontWeight: FontWeight.bold),
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 4),
                  // TITLE
                  Expanded(
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      alignment: Alignment.center,
                      child: Text(
                        title ?? "SELECCIONAR HORA",
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          color: Colors.orange,
                          fontSize: 15,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 4),
                  // SWITCH TO ANALOG CLOCK BUTTON
                  IconButton(
                    style: IconButton.styleFrom(
                      padding: const EdgeInsets.all(4),
                      minimumSize: Size.zero,
                      tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                    ),
                    icon: const Icon(
                      Icons.access_time_filled,
                      color: Colors.orangeAccent,
                      size: 22,
                    ),
                    tooltip: "Cambiar a Reloj Análogo",
                    onPressed: () {
                      switchRequested = true;
                      Navigator.pop(builderContext, null);
                    },
                  ),
                  const SizedBox(width: 4),
                  // CONFIRMAR
                  Flexible(
                    fit: FlexFit.loose,
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      alignment: Alignment.centerRight,
                      child: TextButton(
                        style: TextButton.styleFrom(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 6, vertical: 4),
                          minimumSize: Size.zero,
                          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                        ),
                        onPressed: () => Navigator.pop(
                            builderContext,
                            TimeOfDay(
                                hour: selectedDateTime.hour,
                                minute: selectedDateTime.minute)),
                        child: const Text(
                          "CONFIRMAR",
                          style: TextStyle(
                            color: Colors.orangeAccent,
                            fontSize: 14,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
              const Divider(color: Colors.white24, height: 14),
              // Cupertino Scroll Wheel
              Expanded(
                child: CupertinoTheme(
                  data: const CupertinoThemeData(
                    brightness: Brightness.dark,
                    textTheme: CupertinoTextThemeData(
                      dateTimePickerTextStyle: TextStyle(
                        color: Colors.white,
                        fontSize: 22,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                  child: CupertinoDatePicker(
                    mode: CupertinoDatePickerMode.time,
                    initialDateTime: selectedDateTime,
                    use24hFormat: false,
                    onDateTimeChanged: (DateTime newDate) {
                      selectedDateTime = newDate;
                    },
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );

    if (switchRequested) {
      if (!context.mounted) return null;
      return await _showScrollTimePicker(
        context,
        initialTime: initialTime,
        title: title,
        forceScrollMode: false,
      );
    }
    return result;
  }

  Widget _buildNotesSection(WorkDay day, {BuildContext? dialogContext}) {
    final BuildContext ctx = dialogContext ?? context;
    if (day.notas.isNotEmpty) {
      return Container(
        width: double.infinity,
        margin: const EdgeInsets.only(top: 8),
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: _isDarkMode
              ? Colors.orange.withAlpha(25)
              : const Color(0xFFFEF3C7),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: _isDarkMode
                  ? Colors.orangeAccent.withAlpha(100)
                  : const Color(0xFFFCD34D),
              width: _isDarkMode ? 1.0 : 1.4),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Row(
                  children: [
                    Icon(Icons.note_alt_outlined,
                        color: _isDarkMode
                            ? Colors.orangeAccent
                            : const Color(0xFFD97706),
                        size: 16),
                    const SizedBox(width: 6),
                    Text("NOTAS:",
                        style: TextStyle(
                            color: _isDarkMode
                                ? Colors.orangeAccent
                                : const Color(0xFF334155),
                            fontWeight: FontWeight.bold,
                            fontSize: 13)),
                  ],
                ),
                InkWell(
                  onTap: () async {
                    final String? newNotes = await _promptForNotes(ctx,
                        initialNotes: day.notas);
                    if (newNotes != null) {
                      setState(() {
                        day.notas = newNotes;
                      });
                      await _userHistory.doc(day.id).set(day.toJson());
                      await _saveData();
                    }
                  },
                  child: Text("Editar",
                      style: TextStyle(
                          color: _isDarkMode
                              ? Colors.orangeAccent
                              : const Color(0xFFB45309),
                          fontSize: 12,
                          decoration: TextDecoration.underline)),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(day.notas,
                style: TextStyle(
                    color: _isDarkMode ? Colors.white : Colors.black,
                    fontSize: 13,
                    fontWeight: FontWeight.w600)),
          ],
        ),
      );
    } else {
      return Padding(
        padding: const EdgeInsets.only(top: 8),
        child: SizedBox(
          width: double.infinity,
          child: ElevatedButton.icon(
            style: ElevatedButton.styleFrom(
              backgroundColor: _isDarkMode
                  ? Colors.orange.withAlpha(25)
                  : const Color(0xFFFEF3C7),
              foregroundColor: _isDarkMode
                  ? Colors.orangeAccent
                  : const Color(0xFF78350F),
              elevation: _isDarkMode ? 0 : 1,
              side: BorderSide(
                color: _isDarkMode
                    ? Colors.orangeAccent.withAlpha(120)
                    : const Color(0xFFD97706),
                width: _isDarkMode ? 1.2 : 1.5,
              ),
              minimumSize: const Size(double.infinity, 48),
              padding: const EdgeInsets.symmetric(vertical: 12),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(10),
              ),
            ),
            icon: const Icon(Icons.note_add_outlined, size: 20),
            label: const Text(
              "Agregar notas",
              style: TextStyle(
                fontSize: 15,
                fontWeight: FontWeight.bold,
              ),
            ),
            onPressed: () async {
              final String? newNotes =
                  await _promptForNotes(ctx, initialNotes: "");
              if (newNotes != null && newNotes.isNotEmpty) {
                setState(() {
                  day.notas = newNotes;
                });
                await _userHistory.doc(day.id).set(day.toJson());
                await _saveData();
              }
            },
          ),
        ),
      );
    }
  }

