                final DateTime? sDate = DateTime.tryParse(sDateStr);
                final DateTime? eDate =
                    eDateStr != null ? DateTime.tryParse(eDateStr) : null;

                // Status calculation
                bool isActive = false;
                bool isFuture = false;

                if (sDate != null) {
