                      DateTime(sDate.year, sDate.month, sDate.day);
                  final eMidnight = eDate != null
                      ? DateTime(eDate.year, eDate.month, eDate.day)
                      : null;

                  if (todayMidnight.isBefore(sMidnight)) {
                    isFuture = true;
                  } else if (eMidnight != null &&
                      todayMidnight.isAfter(eMidnight)) {
