                decoration: BoxDecoration(
                  color: widget.isDarkMode
                      ? Colors.white.withAlpha(8)
                      : Colors.grey.withAlpha(20),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Row(
                  children: [
                    const SizedBox(width: 38),
                    Expanded(
                      flex: 3,
                      child: Text(
                        "CAMPO",
                        style: TextStyle(
