        backgroundColor:
            _isDarkMode ? const Color(0xFF1E1E26) : Colors.white,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: Row(
          children: [
            const Icon(Icons.logout_rounded, color: Colors.redAccent, size: 26),
            const SizedBox(width: 10),
            Text(
              "Cerrar Sesión",
              style: TextStyle(
                color: _isDarkMode ? Colors.white : const Color(0xFF0F172A),
                fontWeight: FontWeight.bold,
              ),
            ),
          ],
        ),
        content: Text(
          "¿Estás seguro de que deseas salir del Panel de Administración?",
          style: TextStyle(
            color: _isDarkMode ? Colors.white70 : const Color(0xFF475569),
            fontSize: 15,
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(
              "CANCELAR",
              style: TextStyle(
                color: _isDarkMode ? Colors.white60 : Colors.black54,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.redAccent,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(10)),
            ),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text(
              "SALIR",
              style: TextStyle(
                color: Colors.white,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
        ],
      ),
    );

    if (confirmed == true) {
      await FirebaseAuth.instance.signOut();
    }
  }

  void _copyToClipboard(String text, String label) {
    Clipboard.setData(ClipboardData(text: text));
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text("Copiado $label al portapapeles: $text"),
        backgroundColor: Colors.amber.shade800,
        behavior: SnackBarBehavior.floating,
        duration: const Duration(seconds: 2),
      ),
    );
  }

  Color get _bg =>
      _isDarkMode ? const Color(0xFF0F0F12) : const Color(0xFFF8FAFC);
  Color get _surface =>
      _isDarkMode ? const Color(0xFF16161D) : Colors.white;
  Color get _cardBg =>
      _isDarkMode ? const Color(0xFF1C1C24) : Colors.white;
  Color get _border =>
      _isDarkMode ? Colors.white12 : const Color(0xFFE2E8F0);
  Color get _textPrimary =>
      _isDarkMode ? Colors.white : const Color(0xFF0F172A);
  Color get _textSecondary =>
      _isDarkMode ? Colors.white70 : const Color(0xFF64748B);

  Widget _buildMetricCard({
    required String title,
    required String value,
    required String subtitle,
    required IconData icon,
    required List<Color> gradient,
  }) {
    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: _cardBg,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: _border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  gradient: LinearGradient(colors: gradient),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Icon(icon, color: Colors.white, size: 18),
              ),
              Text(
                title,
                style: TextStyle(
                  color: _textSecondary,
                  fontSize: 10,
                  fontWeight: FontWeight.bold,
                  letterSpacing: 0.5,
                ),
              ),
            ],
          ),
          Text(
            value,
            style: TextStyle(
              color: _textPrimary,
              fontSize: 24,
              fontWeight: FontWeight.w900,
            ),
          ),
          Text(
            subtitle,
            style: TextStyle(
              color: _textSecondary,
              fontSize: 11,
            ),
            overflow: TextOverflow.ellipsis,
          ),
        ],
      ),
    );
  }

  Widget _buildResumenTab() {
    if (_isLoadingMetrics) {
      return Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            const CircularProgressIndicator(color: Colors.amber),
            const SizedBox(height: 16),
            Text(
              "Cargando métricas de usuarios...",
              style: TextStyle(color: _textSecondary, fontSize: 15),
            ),
          ],
        ),
      );
    }

    if (_metricsError != null) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(Icons.error_outline_rounded,
                  color: Colors.redAccent, size: 48),
              const SizedBox(height: 12),
              Text(
                "Error al cargar métricas",
                style: TextStyle(
                  color: _textPrimary,
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                _metricsError!,
                textAlign: TextAlign.center,
                style: TextStyle(color: _textSecondary, fontSize: 13),
              ),
              const SizedBox(height: 16),
              ElevatedButton.icon(
                icon: const Icon(Icons.refresh, color: Colors.black),
                label: const Text("REINTENTAR",
                    style: TextStyle(
                        color: Colors.black, fontWeight: FontWeight.bold)),
                style: ElevatedButton.styleFrom(backgroundColor: Colors.amber),
                onPressed: _loadAdminMetrics,
              ),
            ],
          ),
        ),
      );
    }

    final double adoptionPercent =
        _totalUsers > 0 ? (_realEmailUsers / _totalUsers * 100) : 0.0;

    return RefreshIndicator(
      onRefresh: _loadAdminMetrics,
      color: Colors.amber,
      child: SingleChildScrollView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Top Welcome / Overview Bar
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      "Resumen del Sistema",
                      style: TextStyle(
                        color: _textPrimary,
                        fontSize: 22,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      "Cuentas, directorio y estado de migración",
                      style: TextStyle(color: _textSecondary, fontSize: 14),
                    ),
                  ],
                ),
                IconButton(
                  icon: const Icon(Icons.refresh_rounded, color: Colors.amber),
                  tooltip: "Actualizar métricas",
                  onPressed: _loadAdminMetrics,
                ),
              ],
            ),
            const SizedBox(height: 20),

            // 4 Metrics Grid
            LayoutBuilder(
              builder: (context, constraints) {
                final isWide = constraints.maxWidth > 700;
                final crossAxisCount = isWide ? 4 : 2;
                final aspectRatio = isWide ? 1.6 : 1.35;

                return GridView.count(
                  crossAxisCount: crossAxisCount,
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  crossAxisSpacing: 14,
                  mainAxisSpacing: 14,
                  childAspectRatio: aspectRatio,
                  children: [
                    _buildMetricCard(
                      title: "TOTAL CUENTAS",
                      value: "$_totalUsers",
                      subtitle: "Colección users",
                      icon: Icons.groups_rounded,
                      gradient: const [Color(0xFF4F46E5), Color(0xFF6366F1)],
                    ),
                    _buildMetricCard(
                      title: "ACTIVAS",
                      value: "$_activeUsers",
                      subtitle: "Sin fusionar",
                      icon: Icons.verified_user_rounded,
                      gradient: const [Color(0xFF059669), Color(0xFF10B981)],
                    ),
                    _buildMetricCard(
                      title: "FUSIONADAS",
                      value: "$_mergedUsers",
                      subtitle: "Cuentas archivadas",
                      icon: Icons.archive_rounded,
                      gradient: const [Color(0xFFD97706), Color(0xFFF59E0B)],
                    ),
                    _buildMetricCard(
                      title: "DIRECTORIO",
                      value: "$_directoryCount",
                      subtitle: "Mapeos emp_dir",
                      icon: Icons.badge_rounded,
                      gradient: const [Color(0xFF0284C7), Color(0xFF38BDF8)],
                    ),
                  ],
                );
              },
            ),

            const SizedBox(height: 20),

            // Adoption Progress Card
            Container(
              padding: const EdgeInsets.all(18),
              decoration: BoxDecoration(
                color: _cardBg,
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: _border),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Row(
                        children: [
                          const Icon(Icons.mark_email_read_rounded,
                              color: Colors.amber, size: 22),
                          const SizedBox(width: 10),
                          Text(
                            "Adopción de Correo Real",
                            style: TextStyle(
                              color: _textPrimary,
                              fontSize: 16,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 10, vertical: 4),
                        decoration: BoxDecoration(
                          color: Colors.amber.withAlpha(_isDarkMode ? 35 : 25),
                          borderRadius: BorderRadius.circular(20),
                          border: Border.all(color: Colors.amber.withAlpha(90)),
                        ),
                        child: Text(
                          "${adoptionPercent.toStringAsFixed(1)}%",
                          style: const TextStyle(
                            color: Colors.amber,
                            fontWeight: FontWeight.bold,
                            fontSize: 14,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  ClipRRect(
                    borderRadius: BorderRadius.circular(8),
                    child: LinearProgressIndicator(
                      value: _totalUsers > 0
                          ? (_realEmailUsers / _totalUsers).clamp(0.0, 1.0)
                          : 0.0,
                      minHeight: 10,
                      backgroundColor:
                          _isDarkMode ? Colors.white12 : const Color(0xFFE2E8F0),
                      valueColor:
                          const AlwaysStoppedAnimation<Color>(Colors.amber),
                    ),
                  ),
                  const SizedBox(height: 10),
                  Text(
                    "$_realEmailUsers de $_totalUsers cuentas registradas usan correo personal/institucional (@gmail, @outlook, etc.).",
                    style: TextStyle(color: _textSecondary, fontSize: 13),
                  ),
                ],
              ),
            ),

            const SizedBox(height: 28),

            // Search Header
            Row(
              children: [
                const Icon(Icons.person_search_rounded,
                    color: Colors.amber, size: 24),
                const SizedBox(width: 10),
                Text(
                  "Explorador de Usuarios",
                  style: TextStyle(
                    color: _textPrimary,
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const Spacer(),
                Text(
                  _unitManagerCount > 0
                      ? "Mostrando ${_filteredUsers.length} de $_totalUsers ($_unitManagerCount Ing. Unidad)"
                      : "Mostrando ${_filteredUsers.length} de $_totalUsers",
                  style: TextStyle(color: _textSecondary, fontSize: 12),
                ),
              ],
            ),
            const SizedBox(height: 12),

            // Search TextField
            TextField(
              controller: _searchController,
              style: TextStyle(color: _textPrimary),
              decoration: InputDecoration(
                hintText:
                    "Buscar por No. Empleado, nombre, correo o UID...",
                hintStyle: TextStyle(color: _textSecondary),
                prefixIcon:
                    Icon(Icons.search_rounded, color: _textSecondary),
                suffixIcon: _searchController.text.isNotEmpty
                    ? IconButton(
                        icon:
                            Icon(Icons.clear_rounded, color: _textSecondary),
                        onPressed: () {
                          _searchController.clear();
                        },
                      )
                    : null,
                filled: true,
                fillColor: _cardBg,
                contentPadding: const EdgeInsets.symmetric(
                    horizontal: 16, vertical: 14),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(14),
                  borderSide: BorderSide(color: _border),
                ),
                enabledBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(14),
                  borderSide: BorderSide(color: _border),
                ),
                focusedBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(14),
                  borderSide: const BorderSide(color: Colors.amber, width: 1.5),
                ),
              ),
            ),
            const SizedBox(height: 16),

            // Users List
            if (_filteredUsers.isEmpty)
              Container(
                padding: const EdgeInsets.all(32),
                alignment: Alignment.center,
                child: Column(
                  children: [
                    Icon(Icons.search_off_rounded,
                        color: _textSecondary, size: 48),
                    const SizedBox(height: 12),
                    Text(
                      "No se encontraron cuentas con ese criterio",
                      style: TextStyle(color: _textSecondary, fontSize: 15),
                    ),
                  ],
                ),
              )
            else
              ListView.separated(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                itemCount: _filteredUsers.length,
                separatorBuilder: (context, index) =>
                    const SizedBox(height: 10),
                itemBuilder: (context, index) {
                  final u = _filteredUsers[index];
                  final bool isMerged = u['isMerged'] == true;
                  final bool isUnitManager = u['isUnitManager'] == true;
                  final String emp = u['emp'] ?? '';
                  final String name = u['name'] ?? 'Sin nombre';
                  final String email = u['email'] ?? '';
                  final String rec = u['recEmail'] ?? '';
                  final String uid = u['uid'] ?? '';
                  final String displayEmail =
                      (email.isNotEmpty && !email.endsWith('@televisa.com'))
                          ? email
                          : (rec.isNotEmpty ? rec : email);

                  final Color unitManagerColor = _isDarkMode
                      ? Colors.cyanAccent
                      : const Color(0xFF0284C7);

                  return Container(
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      color: _cardBg,
                      borderRadius: BorderRadius.circular(14),
                      border: Border.all(
                        color: isMerged
                            ? Colors.orange.withAlpha(_isDarkMode ? 80 : 100)
                            : (isUnitManager
                                ? unitManagerColor.withAlpha(_isDarkMode ? 90 : 110)
                                : _border),
                        width: isUnitManager && !isMerged ? 1.5 : 1.0,
                      ),
                    ),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.center,
                      children: [
                        // Avatar Circle
                        CircleAvatar(
                          radius: 20,
                          backgroundColor: isMerged
                              ? Colors.orange.withAlpha(40)
                              : (isUnitManager
                                  ? unitManagerColor.withAlpha(_isDarkMode ? 40 : 30)
                                  : Colors.amber.withAlpha(40)),
                          child: Text(
                            emp.isNotEmpty
                                ? emp.substring(0, 1)
                                : (name.isNotEmpty ? name.substring(0, 1) : '?'),
                            style: TextStyle(
                              color: isMerged
                                  ? Colors.orange
                                  : (isUnitManager
                                      ? unitManagerColor
                                      : Colors.amber),
                              fontWeight: FontWeight.bold,
                              fontSize: 16,
                            ),
                          ),
                        ),
                        const SizedBox(width: 14),

                        // Details Column
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                children: [
                                  Flexible(
                                    child: Text(
                                      name,
                                      style: TextStyle(
                                        color: _textPrimary,
                                        fontWeight: FontWeight.bold,
                                        fontSize: 15,
                                      ),
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ),
                                  const SizedBox(width: 8),
                                  if (isMerged)
                                    Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 6, vertical: 2),
                                      decoration: BoxDecoration(
                                        color: Colors.orange.withAlpha(40),
                                        borderRadius: BorderRadius.circular(6),
                                      ),
                                      child: const Text(
                                        "FUSIONADO",
                                        style: TextStyle(
                                          color: Colors.orange,
                                          fontSize: 10,
                                          fontWeight: FontWeight.bold,
                                        ),
                                      ),
                                    )
                                  else
                                    Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 6, vertical: 2),
                                      decoration: BoxDecoration(
                                        color: Colors.green.withAlpha(40),
                                        borderRadius: BorderRadius.circular(6),
                                      ),
                                      child: const Text(
                                        "ACTIVO",
                                        style: TextStyle(
                                          color: Colors.greenAccent,
                                          fontSize: 10,
                                          fontWeight: FontWeight.bold,
                                        ),
                                      ),
                                    ),
                                  if (isUnitManager) ...[
                                    const SizedBox(width: 6),
                                    Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 6, vertical: 2),
                                      decoration: BoxDecoration(
                                        color: unitManagerColor.withAlpha(_isDarkMode ? 35 : 25),
                                        borderRadius: BorderRadius.circular(6),
                                        border: Border.all(
                                          color: unitManagerColor.withAlpha(120),
                                        ),
                                      ),
                                      child: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Icon(
                                            Icons.shield_rounded,
                                            size: 11,
                                            color: unitManagerColor,
                                          ),
                                          const SizedBox(width: 4),
                                          Text(
                                            "ING. DE UNIDAD",
                                            style: TextStyle(
                                              color: unitManagerColor,
                                              fontSize: 10,
                                              fontWeight: FontWeight.bold,
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ],
                                ],
                              ),
                              const SizedBox(height: 4),
                              Row(
                                children: [
                                  if (emp.isNotEmpty) ...[
                                    Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 6, vertical: 1),
                                      decoration: BoxDecoration(
                                        color: _border,
                                        borderRadius: BorderRadius.circular(4),
                                      ),
                                      child: Text(
                                        "No. $emp",
                                        style: TextStyle(
                                          color: _textPrimary,
                                          fontSize: 12,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ),
                                    const SizedBox(width: 8),
                                  ],
                                  Flexible(
                                    child: Text(
                                      displayEmail.isNotEmpty
                                          ? displayEmail
                                          : uid,
                                      style: TextStyle(
                                        color: _textSecondary,
                                        fontSize: 12,
                                      ),
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ),
                                ],
                              ),
                              if (isMerged && u['mergedInto'] != '')
                                Padding(
                                  padding: const EdgeInsets.only(top: 4),
                                  child: Text(
                                    "Destino UID: ${u['mergedInto']}",
                                    style: TextStyle(
                                      color: Colors.orange.shade300,
                                      fontSize: 11,
                                    ),
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                ),
                            ],
                          ),
                        ),

                        // Actions
                        IconButton(
                          icon: Icon(
                            isUnitManager
                                ? Icons.shield_rounded
                                : Icons.shield_outlined,
                            color: isUnitManager
                                ? unitManagerColor
                                : _textSecondary,
                            size: 22,
                          ),
                          tooltip: isUnitManager
                              ? "Revocar Ingeniero de Unidad"
                              : "Asignar Ingeniero de Unidad",
                          onPressed: () => _promptToggleUnitManager(
                            uid: uid,
                            userName: name,
                            employeeNumber: emp,
                            currentIsUnitManager: isUnitManager,
                          ),
                        ),
                        PopupMenuButton<String>(
                          icon: Icon(Icons.more_vert_rounded,
                              color: _textSecondary, size: 20),
                          tooltip: "Más opciones",
                          color: _cardBg,
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                            side: BorderSide(color: _border),
                          ),
                          onSelected: (val) {
                            if (val == 'toggle_unit_manager') {
                              _promptToggleUnitManager(
                                uid: uid,
                                userName: name,
                                employeeNumber: emp,
                                currentIsUnitManager: isUnitManager,
                              );
                            } else if (val == 'send_reset') {
                              _promptSendPasswordReset(
                                userName: name,
                                displayEmail: displayEmail,
                                employeeNumber: emp,
                              );
                            } else if (val == 'change_email') {
                              _showChangeEmailDialog(
                                uid: uid,
                                userName: name,
                                currentEmail: displayEmail,
                                employeeNumber: emp,
                              );
                            } else if (val == 'copy_uid') {
                              _copyToClipboard(uid, "UID");
                            } else if (val == 'migrate') {
                              final targetQuery =
                                  emp.isNotEmpty ? emp : displayEmail;
                              _copyToClipboard(targetQuery, "identificador");
                              setState(() => _currentTab = 1);
                            }
                          },
                          itemBuilder: (ctx) => [
                            PopupMenuItem(
                              value: 'toggle_unit_manager',
                              child: Row(
                                children: [
                                  Icon(
                                    isUnitManager
                                        ? Icons.shield_outlined
                                        : Icons.shield_rounded,
                                    color: isUnitManager
                                        ? Colors.amber.shade800
                                        : unitManagerColor,
                                    size: 18,
                                  ),
                                  const SizedBox(width: 10),
                                  Text(
                                    isUnitManager
                                        ? "Revocar Ingeniero de Unidad"
                                        : "Asignar Ingeniero de Unidad",
                                    style: TextStyle(
                                      color: _textPrimary,
                                      fontSize: 13,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            PopupMenuItem(
                              value: 'send_reset',
                              child: Row(
                                children: [
                                  Icon(Icons.lock_reset_rounded,
                                      color: _isDarkMode
                                          ? Colors.cyanAccent
                                          : const Color(0xFF0284C7),
                                      size: 18),
                                  const SizedBox(width: 10),
                                  Text(
                                    "Enviar Restablecimiento",
                                    style: TextStyle(
                                        color: _textPrimary, fontSize: 13),
                                  ),
                                ],
                              ),
                            ),
                            PopupMenuItem(
                              value: 'change_email',
                              child: Row(
                                children: [
                                  Icon(Icons.alternate_email_rounded,
                                      color: _isDarkMode
                                          ? Colors.tealAccent
                                          : const Color(0xFF0D9488),
                                      size: 18),
                                  const SizedBox(width: 10),
                                  Text(
                                    "Cambiar Correo",
                                    style: TextStyle(
                                        color: _textPrimary, fontSize: 13),
                                  ),
                                ],
                              ),
                            ),
                            PopupMenuItem(
                              value: 'copy_uid',
                              child: Row(
                                children: [
                                  Icon(Icons.copy_rounded,
                                      color: _textSecondary, size: 18),
                                  const SizedBox(width: 10),
                                  Text(
                                    "Copiar UID",
                                    style: TextStyle(
                                        color: _textPrimary, fontSize: 13),
                                  ),
                                ],
                              ),
                            ),
                            PopupMenuItem(
                              value: 'migrate',
                              child: Row(
                                children: [
                                  const Icon(Icons.merge_type_rounded,
                                      color: Colors.amber, size: 18),
                                  const SizedBox(width: 10),
                                  Text(
                                    "Migrar cuenta",
                                    style: TextStyle(
                                        color: _textPrimary, fontSize: 13),
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      ],
                    ),
                  );
                },
              ),
            const SizedBox(height: 30),
          ],
        ),
      ),
    );
  }

  Widget _buildMigracionTab() {
    return AdminAccountMergeScreen(
      isDarkMode: _isDarkMode,
      isEmbedded: true,
      onMergeComplete: _loadAdminMetrics,
    );
  }

  Widget _buildAjustesTab() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            "Ajustes de Administración",
            style: TextStyle(
              color: _textPrimary,
              fontSize: 22,
              fontWeight: FontWeight.bold,
            ),
          ),
          const SizedBox(height: 6),
          Text(
            "Configuración del portal e identidad administrativa",
            style: TextStyle(color: _textSecondary, fontSize: 14),
          ),
          const SizedBox(height: 20),

          // Admin Identity Card
          Container(
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: [
                  Colors.amber.withAlpha(_isDarkMode ? 30 : 25),
                  Colors.orange.withAlpha(_isDarkMode ? 15 : 10),
                ],
              ),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: Colors.amber.withAlpha(_isDarkMode ? 90 : 120),
              ),
            ),
            child: Row(
              children: [
                const CircleAvatar(
                  radius: 28,
                  backgroundColor: Colors.amber,
                  child: Icon(Icons.admin_panel_settings_rounded,
                      color: Colors.black, size: 30),
                ),
                const SizedBox(width: 16),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          const Text(
                            "Super Administrador",
                            style: TextStyle(
                              color: Colors.amber,
                              fontWeight: FontWeight.bold,
                              fontSize: 16,
                            ),
                          ),
                          const SizedBox(width: 8),
                          Container(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 6, vertical: 2),
                            decoration: BoxDecoration(
                              color: Colors.amber.withAlpha(40),
                              borderRadius: BorderRadius.circular(6),
                            ),
                            child: const Text(
                              "ROOT",
                              style: TextStyle(
                                color: Colors.amber,
                                fontWeight: FontWeight.bold,
                                fontSize: 10,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 4),
                      Text(
                        kAdminEmail,
                        style: TextStyle(
                          color: _textPrimary,
                          fontSize: 14,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        "UID: $kAdminUid",
                        style: TextStyle(color: _textSecondary, fontSize: 11),
                        overflow: TextOverflow.ellipsis,
                      ),
                    ],
                  ),
                ),
                IconButton(
                  icon: const Icon(Icons.copy_rounded, color: Colors.amber),
                  tooltip: "Copiar UID del Administrador",
                  onPressed: () =>
                      _copyToClipboard(kAdminUid, "UID Administrador"),
                ),
              ],
            ),
          ),

          const SizedBox(height: 20),

          // Appearance Card
          Container(
            decoration: BoxDecoration(
              color: _cardBg,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _border),
            ),
            child: SwitchListTile(
              secondary: Icon(
                _isDarkMode ? Icons.dark_mode_rounded : Icons.light_mode_rounded,
                color: Colors.amber,
              ),
              title: Text(
                _isDarkMode ? "Modo Oscuro" : "Modo Luz de Día",
                style: TextStyle(
                  color: _textPrimary,
                  fontWeight: FontWeight.bold,
                  fontSize: 16,
                ),
              ),
              subtitle: Text(
                _isDarkMode
                    ? "Tema de alto contraste nocturno"
                    : "Tema luminoso para luz natural",
                style: TextStyle(color: _textSecondary, fontSize: 13),
              ),
              value: _isDarkMode,
              activeColor: Colors.amber,
              onChanged: (_) => _toggleTheme(),
            ),
          ),

          const SizedBox(height: 20),

          // System Info Card
          Container(
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              color: _cardBg,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _border),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  "Información del Sistema",
                  style: TextStyle(
                    color: _textPrimary,
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 12),
                _buildInfoRow("Versión Aplicación", "v.23.16.0 03/11/26"),
                const Divider(height: 20),
                _buildInfoRow("Entorno", "Firebase Production (Hosting & Firestore)"),
                const Divider(height: 20),
                _buildInfoRow("Reglas de Seguridad",
                    "Bypass Superadmin Activo (minominapro@gmail.com)"),
                const Divider(height: 20),
                _buildInfoRow("Modo Operativo", "Consola Administrativa Exclusiva"),
              ],
            ),
          ),

          const SizedBox(height: 28),

          // Logout Button
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.redAccent.shade700,
              foregroundColor: Colors.white,
              minimumSize: const Size(double.infinity, 52),
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(14)),
              elevation: 2,
            ),
            icon: const Icon(Icons.logout_rounded, size: 20),
            label: const Text(
              "CERRAR SESIÓN DE ADMINISTRADOR",
              style: TextStyle(
                fontSize: 15,
                fontWeight: FontWeight.bold,
                letterSpacing: 0.5,
              ),
            ),
            onPressed: _confirmSignOut,
          ),
          const SizedBox(height: 40),
        ],
      ),
    );
  }

  Widget _buildInfoRow(String label, String value) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Text(label, style: TextStyle(color: _textSecondary, fontSize: 13)),
        const SizedBox(width: 10),
        Flexible(
          child: Text(
            value,
            textAlign: TextAlign.end,
            style: TextStyle(
              color: _textPrimary,
              fontWeight: FontWeight.w600,
              fontSize: 13,
            ),
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _bg,
      appBar: AppBar(
        backgroundColor: _surface,
        elevation: 0,
        title: Row(
          children: [
            Container(
              padding: const EdgeInsets.all(7),
              decoration: BoxDecoration(
                color: Colors.amber.withAlpha(_isDarkMode ? 35 : 25),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: Colors.amber.withAlpha(90)),
              ),
              child: const Icon(Icons.shield_rounded,
                  color: Colors.amber, size: 20),
            ),
            const SizedBox(width: 12),
            Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  "Mi Nómina Pro",
                  style: TextStyle(
                    color: _textPrimary,
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const Text(
                  "PORTAL DE ADMINISTRACIÓN",
                  style: TextStyle(
                    color: Colors.amber,
                    fontSize: 10,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 1.0,
                  ),
                ),
              ],
            ),
          ],
        ),
        actions: [
          IconButton(
            icon: Icon(
              _isDarkMode
                  ? Icons.light_mode_rounded
                  : Icons.dark_mode_rounded,
              color: Colors.amber,
            ),
            tooltip: _isDarkMode ? "Modo Luz de Día" : "Modo Oscuro",
            onPressed: _toggleTheme,
          ),
          IconButton(
            icon: Icon(Icons.logout_rounded, color: Colors.redAccent.shade100),
            tooltip: "Cerrar sesión",
            onPressed: _confirmSignOut,
          ),
          const SizedBox(width: 8),
        ],
      ),
      body: IndexedStack(
        index: _currentTab,
        children: [
          _buildResumenTab(),
          _buildMigracionTab(),
          _buildAjustesTab(),
        ],
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          color: _surface,
          border: Border(top: BorderSide(color: _border)),
        ),
        child: BottomNavigationBar(
          currentIndex: _currentTab,
          onTap: (index) {
            setState(() => _currentTab = index);
            if (index == 0) {
              _loadAdminMetrics();
            }
          },
          backgroundColor: _surface,
          selectedItemColor: Colors.amber,
          unselectedItemColor: _textSecondary,
          selectedLabelStyle:
              const TextStyle(fontWeight: FontWeight.bold, fontSize: 12),
          unselectedLabelStyle:
              const TextStyle(fontWeight: FontWeight.w500, fontSize: 11),
          type: BottomNavigationBarType.fixed,
          elevation: 0,
          items: const [
            BottomNavigationBarItem(
              icon: Icon(Icons.analytics_outlined),
              activeIcon: Icon(Icons.analytics_rounded),
              label: "Resumen",
            ),
            BottomNavigationBarItem(
              icon: Icon(Icons.merge_type_outlined),
              activeIcon: Icon(Icons.merge_type_rounded),
              label: "Migración",
            ),
            BottomNavigationBarItem(
              icon: Icon(Icons.admin_panel_settings_outlined),
              activeIcon: Icon(Icons.admin_panel_settings_rounded),
              label: "Ajustes Admin",
            ),
          ],
        ),
      ),
    );
  }
}



